-- Reference data used by the demo. Coordinates are indicative (city-block
-- level), good enough for the office finder map/distance UI; refine with
-- real geocoding before shipping.

TRUNCATE user_documents, user_progress, documents, roadmap_steps, visas, services,
  funding_programs, glossary_terms RESTART IDENTITY CASCADE;

    'Choosing your visa is the very first strategic decision of your project: it determines how quickly you can get set up, the steps you''ll need to complete, and how much freedom you''ll have to grow your business.' || E'\n\n' ||
    'Four main visas are available to foreign founders in Korea. Find the situation that best matches your project to discover the most suitable path, compare the options in detail, then follow the typical journey to the D-8-4 visa.',
    $g1$[{"type": "comparison", "eyebrow": "Comparison", "title": "Which visa matches your profile?", "subtitle": "Four main paths lead to founding a company in Korea. Find the one that matches your situation and compare its requirements, duration, and benefits.", "items": [{"code": "D-8-4", "name": "Tech Investor Visa (OASIS)", "tag": "Standard path", "summary": "This is the standard path for foreign founders. Your application is assessed by KISED using a points-based scale (degrees, experience, intellectual property, funding). Once approved, you register your company and then obtain the visa.", "idealFor": "You have a well-developed project: a solid business plan, a patent, a prototype, or recognized entrepreneurial experience.", "advantages": ["Valid for 1 year, renewable for up to 2 years after confirmation", "Full official recognition and access to KISED support and public funding programs"], "requirements": ["OASIS points-based assessment (degree, experience, patents, funding)", "Company registered in Korea (Chusik or Yuhan Hoesa)", "Capital deposited in a dedicated bank account", "Confirmation letter issued by KISED"], "watchOut": "The OASIS assessment process can take several months."}, {"code": "D-8-4S", "name": "Streamlined path (since November 2024)", "tag": "Fast track \u00b7 2024", "summary": "Thanks to a direct recommendation from your program, your application is processed faster with fewer supporting documents required. This is the fastest path for founders who already have institutional backing.", "idealFor": "You've completed a recognized accelerator program (K-Startup Grand Challenge, TIPS, Born2Global...).", "advantages": ["Valid for 1 year, renewable", "Accelerated processing with reduced supporting documentation"], "requirements": ["Direct recommendation from an approved partner program (K-Startup Grand Challenge, TIPS...)", "Simplified application, without a full points-based assessment", "Company registered in Korea"], "watchOut": "Reserved for founders already selected by a recognized partner program."}, {"code": "D-10-2", "name": "Startup preparation visa", "tag": "Preparation path", "summary": "This temporary long-term stay visa lets you legally remain in Korea to finalize your business plan and put together your OASIS application, before transitioning to the D-8-4.", "idealFor": "You want to explore the Korean market and prepare your application calmly before committing.", "advantages": ["6 months, renewable once", "Lets you prepare your OASIS application and company registration without time pressure"], "requirements": ["Detailed business plan", "Proof of sufficient financial resources", "No company registration required to obtain it"], "watchOut": "Does not allow paid commercial activity - preparation only."}, {"code": "F-2-7", "name": "Points-based talent visa", "tag": "Points-based visa", "summary": "Based on a points scale (age, degree, income, Korean proficiency...), this visa is not tied to a specific company. It offers more freedom but does not replace standard company registration.", "idealFor": "You have a senior profile (advanced degree, professional experience, solid income) and want to keep your activity flexible.", "advantages": ["3 years, renewable, can lead to permanent residency (F-5)", "Great flexibility: change activity, combine statuses, and easier access to permanent residency"], "requirements": ["Minimum score on the points scale (age, degree, experience, income, Korean proficiency)", "Proof of degrees and professional experience", "No mandatory link to a specific company"], "watchOut": "Does not include startup-specific benefits (KISED programs and funding)."}]}, {"type": "checklist", "eyebrow": "Good to know", "title": "Are you a student in Korea (D-2 visa)?", "items": [{"icon": "graduation", "title": "Industry-university cooperation", "description": "If your project was born during your studies, many universities - including PNU - have an industry-university cooperation foundation that can support you in moving from student status to D-8-4 founder status, without leaving the country."}]}, {"type": "timeline", "eyebrow": "The journey", "title": "The path to the D-8-4 visa", "subtitle": "The standard path, via KISED's OASIS program, in seven steps.", "items": [{"title": "Prepare your application", "description": "Gather your degrees, resume, business plan, and proof of experience or patents, translated and apostilled."}, {"title": "Submission on the OASIS platform", "description": "Submit your application online on KISED's platform for assessment under the points-based scale."}, {"title": "Assessment and interview", "description": "KISED reviews your application. An interview may be arranged depending on your profile and industry."}, {"title": "Recommendation letter", "description": "If approved, KISED issues a recommendation letter required for your visa application."}, {"title": "Company registration", "description": "With the KISED recommendation letter in hand, you can finalize your company's legal registration with the commercial court - share capital, articles of incorporation, filing the application.", "stepLink": 4, "stepLinkLabel": "See the registration details"}, {"title": "Submitting the visa application", "description": "File your application with the Korean consulate if you are abroad, or with the local immigration office for a change of status."}, {"title": "Getting your visa and ARC card", "description": "Once your D-8-4 visa is approved, apply for your Alien Registration Card (ARC) within 90 days of entering Korea."}]}, {"type": "checklist", "eyebrow": "After the visa", "title": "What not to forget", "subtitle": "Four essential points to plan for, whichever visa you obtain.", "items": [{"icon": "shield", "title": "Private insurance", "description": "Take out private health insurance covering at least 100 million KRW before submitting your application."}, {"icon": "document", "title": "Clean criminal record", "description": "Provide a clean criminal record extract, apostilled or legalized, along with an official translation."}, {"icon": "id-card", "title": "Resident card (ARC)", "description": "Apply for your Alien Registration Card within 90 days of arrival: it's essential for opening a bank account or signing up for a phone plan."}, {"icon": "refresh", "title": "Annual renewal", "description": "Plan ahead for your visa renewal: the company's actual activity, revenue, and jobs created are reviewed against KISED's criteria."}]}]$g1$::jsonb),
  (2, 'Choose a legal structure', 'Most founders pick a Chusik Hoesa (joint-stock) or a Yuhan Hoesa (limited liability).', 'https://www.startbiz.go.kr',
    'Your company''s legal status determines your level of financial liability, your tax regime, your credibility with banks and investors, and how burdensome your day-to-day administration will be. Changing it after registration remains possible, but proves costly and time-consuming - better to choose well from the start.' || E'\n\n' ||
    'Two statuses account for the vast majority of foreign startup formations in Korea: the Chusik Hoesa (joint-stock company) and the Yuhan Hoesa (limited liability company). Compare them based on your project, then review the key points common to both before registration.',
    $g2$[{"type": "comparison", "eyebrow": "Comparison", "title": "Which structure for your company?", "subtitle": "The two most common statuses for foreign founders in Korea. Compare them to choose the one that best fits your project.", "items": [{"code": "\uc8fc\uc2dd\ud68c\uc0ac", "name": "Chusik Hoesa", "tag": "Joint-stock company", "summary": "The most recognized structure for startups planning to raise funding. It offers more flexibility for bringing in investors and is favored by Korean venture capital funds.", "idealFor": "Startups aiming for fundraising or rapid growth with multiple co-founders.", "advantages": ["Easier share issuance to bring in new investors", "The structure best recognized by VCs, accelerators, and public programs", "Stronger institutional image with banks and partners"], "requirements": ["One shareholder and one director are enough to get started", "Share capital deposited in a dedicated bank account before registration", "Roles and ownership percentages defined in the articles of incorporation before registration"], "watchOut": "More formal governance: general meetings, a shareholder register, and minutes must be kept up to date. A statutory auditor becomes mandatory if capital exceeds 1 billion KRW."}, {"code": "\uc720\ud55c\ud68c\uc0ac", "name": "Yuhan Hoesa", "tag": "Limited liability company", "summary": "A structure that's simpler to set up and run day-to-day, well suited if you're starting out solo or with a small team without an immediate need to bring in outside investors.", "idealFor": "Solo founders or small teams, service or consulting businesses.", "advantages": ["Simplified incorporation and day-to-day management formalities", "No requirement for a statutory auditor", "Lower day-to-day administrative running costs"], "requirements": ["A single member is enough, 100% foreign capital allowed", "Share capital deposited in a dedicated bank account before registration", "Articles of incorporation drafted in accordance with Korean law"], "watchOut": "Less suited if you plan to open your capital to investors: conversion into a Chusik Hoesa remains possible but must be planned ahead."}]}, {"type": "checklist", "eyebrow": "To plan for", "title": "Key points to know", "subtitle": "Four principles that apply regardless of the structure you choose.", "items": [{"icon": "star", "title": "100% foreign capital", "description": "Korea allows foreign founders to hold the entirety of their company's capital, with no local partner required."}, {"icon": "id-card", "title": "A single shareholder is enough", "description": "No requirement to partner with anyone: one person alone can found and hold the entirety of a Chusik Hoesa or a Yuhan Hoesa."}, {"icon": "document", "title": "Statutory auditor", "description": "For a Chusik Hoesa, a statutory auditor becomes mandatory as soon as capital exceeds 1 billion KRW."}, {"icon": "target", "title": "Registration cost", "description": "Budget for roughly 0.4% of registered capital, with a minimum of 112,500 KRW, excluding attorney fees."}]}]$g2$::jsonb),
  (3, 'Secure a business address', 'Secure a registered head office (bonjeom) address for the company.', NULL,
    'This address is not a mere administrative detail: recorded in the articles of incorporation filed with the commercial court, it becomes your 본점 (official head office) and determines where your company may legally operate. Changing it after registration requires updating the articles of incorporation and completing new registry formalities - so it''s best to make the right choice from the start.' || E'\n\n' ||
    'Four main options are available to foreign founders, from virtual offices to personal addresses. Compare them based on cost, what''s included, and the founder profile they suit, then check the points below before signing a lease or accepting a spot in an incubator.',
    $g3$[{"type": "comparison", "eyebrow": "Comparison", "title": "Which address for your head office?", "subtitle": "Four main options are available to foreign founders: compare their cost, what's included, and the profile they suit.", "items": [{"name": "Virtual office", "tag": "Quick setup", "cost": "\u2248 125,000 - 300,000 KRW / month", "includes": "Registrable business address, mail reception and scanning, occasional access to meeting rooms.", "idealFor": "Founders based outside Korea or remote teams who only need a legal address.", "watchOut": "The lease agreement provided must explicitly authorize commercial use and company registration: ask for a template already accepted by the registration office before signing."}, {"name": "Co-working space", "tag": "Flexible", "cost": "from \u2248 120,000 KRW / month for a dedicated desk", "includes": "Dedicated desk or private office, meeting rooms, networking events, registrable address on dedicated plans.", "idealFor": "Small teams who want a real workspace without committing to a traditional commercial lease.", "watchOut": "Only \"private office\" or \"business address\" plans allow registration: a simple open-space membership is generally not accepted by the commercial registry."}, {"name": "Public startup center", "tag": "Free or subsidized", "cost": "Free to very low cost, by selection", "includes": "Workspace, support with registration and visa, mentoring, and networking with investors, through structures such as the Global Startup Center or KISED incubation centers.", "idealFor": "Foreign founders in the founding phase, eligible for government support programs.", "watchOut": "Limited spots awarded by application: allow several weeks of selection time before getting an address usable for registration."}, {"name": "Personal address", "tag": "Economical", "cost": "0 KRW if you already live there", "includes": "Your lease or property title serves directly as proof of head office, at no extra cost.", "idealFor": "Unregulated activities, with no public reception, inventory, or on-site team.", "watchOut": "Many condominium regulations prohibit commercial use of a residential unit, and some activities require commercial zoning: check both points before choosing this option."}]}, {"type": "checklist", "eyebrow": "To plan for", "title": "Four points to check before signing", "subtitle": "Whichever type of address you choose, these elements affect your registration and the rest of your setup.", "items": [{"icon": "document", "title": "Proof of address is mandatory", "description": "Whatever you choose, a lease agreement or property title - in your name or the future company's name - is required in the registration file submitted to the commercial court.", "stepLink": 4, "stepLinkLabel": "See the filing process"}, {"icon": "map-pin", "title": "Your address becomes the official \ubcf8\uc810", "description": "It appears in the articles of incorporation (\uc815\uad00) filed at registration: it becomes your legal head office and determines, among other things, your tax jurisdiction and competent court."}, {"icon": "refresh", "title": "Changing address comes at a cost", "description": "Moving after registration requires an amendment to the articles of incorporation (\ubcf8\uc810\uc774\uc804) and a new entry in the commercial registry, with additional fees and procedures: better to plan for a stable address from the outset."}, {"icon": "alert", "title": "Watch out for zoning", "description": "Some regulated activities (food service, healthcare professions...) require a specific commercial zone: check that your address is compatible with your activity before signing a lease or accepting a spot in an incubator."}]}]$g3$::jsonb),
  (4, 'Register your startup', 'File the incorporation with the commercial registry.', 'https://www.iros.go.kr',
    'This step is the administrative core of your project: without registration, you cannot open a corporate bank account, hire staff, or legally issue invoices. The procedure involves several different authorities - the bank, KOTRA, the commercial court - and each document obtained serves as supporting evidence for the next step.' || E'\n\n' ||
    'Three phases follow one another, from depositing capital to filing the articles of incorporation with the court. Follow them in order, prepare the required documents in advance, and find out what you receive at the end of the process.',
    $g4$[{"type": "timeline", "eyebrow": "The process", "title": "Three phases to register your company", "subtitle": "Each phase produces a document required for the next phase. Follow them in order.", "items": [{"title": "Investment notification and capital deposit", "description": "Before any other step, notify your foreign direct investment to KOTRA or a bank licensed for foreign exchange, then transfer the declared capital to a temporary foreign-currency account.", "items": ["Foreign exchange transaction certificate (\uc678\uad6d\ud658\uac70\ub798\uc2e0\uace0\ud544\uc99d)", "Deposit balance certificate confirming the capital paid in"], "badge": "KOTRA"}, {"title": "Company name reservation", "description": "Check availability and reserve your company name with the court registry. Names must comply with Korean naming conventions and industry classifications - a step that often creates delays without professional support.", "items": ["Company name compliant with Korean industry classifications", "Availability confirmation from the registry"], "badge": "Start-Biz Online"}, {"title": "Filing the articles of incorporation and application with the court", "description": "Submit the full application to the commercial court. If an agent files the application on your behalf, powers of attorney must be provided in two copies.", "items": ["Copy of the articles of incorporation", "Deposit balance certificate", "Apostilled passports of directors and shareholders", "Notarized power of attorney (two copies if filed by an agent)"], "badge": "Internet Registry Office"}]}, {"type": "columns", "eyebrow": "To prepare", "title": "Two types of documents to plan for", "subtitle": "Some documents are obtained in Korea over the course of the process, while others must be prepared in advance in your home country.", "columns": [{"icon": "map-pin", "title": "Obtained in Korea during the process", "items": ["Foreign exchange transaction certificate (\uc678\uad6d\ud658\uac70\ub798\uc2e0\uace0\ud544\uc99d)", "Deposit balance certificate", "Company name reservation confirmation"]}, {"icon": "globe", "title": "To prepare in your home country", "items": ["Articles of incorporation, drafted under Korean law", "Passports of directors and shareholders, apostilled", "Notarized power of attorney if an agent files the application", "Shareholder resolutions, if required"], "note": "All foreign documents (articles of incorporation, power of attorney, resolutions) require notarization followed by an apostille or consular legalization, as well as an official Korean translation."}]}, {"type": "checklist", "eyebrow": "What you get", "title": "What you receive at the end of the process", "subtitle": "Two official documents that establish your company's legal existence - and that you'll use immediately in the next step.", "items": [{"icon": "id-card", "title": "\ubc95\uc778\ub4f1\ub85d\ubc88\ud638 \u00b7 Corporate registration number", "description": "Issued by the commercial court via the Internet Registry Office, this number officially identifies your company and certifies its legal existence."}, {"icon": "document", "title": "\uc778\uac10\uc99d\uba85\uc11c \u00b7 Corporate seal certificate", "description": "The \uc778\uac10 (corporate seal) and its official certificate are used to authenticate the company's legal and banking documents."}]}]$g4$::jsonb),
  (5, 'Open a bank account', 'Open a corporate bank account with your incorporation certificate.', NULL,
    'Opening a corporate bank account turns the capital held in the temporary account into actual company cash flow. Korean banks apply strict anti-money-laundering checks - an in-branch visit is often required, along with a substantial set of documents - and then impose deadlines you must meet to finalize your foreign-invested company status with KOTRA, with penalties if you miss them.' || E'\n\n' ||
    'Some Korean banks are markedly more experienced with foreign founders'' applications than others: compare them before choosing your branch, then follow the timeline of deadlines to meet once your account is open.',
    $g5$[{"type": "comparison", "eyebrow": "Comparison", "title": "Which bank for your corporate account?", "subtitle": "All major Korean banks can open a corporate account, but some are markedly more experienced with foreign founders' applications.", "items": [{"name": "KEB Hana Bank", "tag": "The most international", "summary": "Considered the most accessible bank for foreigners: mobile app available in English and dedicated \"Global\" branches for foreign residents and foreign-invested companies.", "advantages": ["App and customer service in English", "Global branches in major cities"]}, {"name": "Woori Bank", "tag": "The largest branch network", "summary": "Has a department dedicated to foreign-invested companies and a very large branch network, useful if your head office is located outside Seoul.", "advantages": ["Dedicated foreign-invested company department", "Branches in most major cities"]}, {"name": "Shinhan Bank", "tag": "Shinhan Global international network", "summary": "Its \"Shinhan Global\" network is present in several home countries of foreign investors, which can make it easier to get in touch even before you arrive in Korea.", "advantages": ["Shinhan subsidiaries in several countries", "Dedicated service for foreign companies"]}, {"name": "KB Kookmin Bank", "tag": "The largest retail bank", "summary": "Korea's leading retail bank by number of branches, with a department specialized in supporting foreign direct investment (FDI) companies.", "advantages": ["The country's densest branch network", "Dedicated FDI department"]}]}, {"type": "timeline", "eyebrow": "Timeline", "title": "Deadlines to meet after depositing capital", "subtitle": "Once the corporate account is open, several deadlines follow one another - some with direct consequences if missed.", "items": [{"title": "Day 0 \u2014 Capital already deposited in a temporary account", "description": "When you notified your investment, your capital was paid into a temporary account opened in the future representative's name - this is the capital that will be transferred to the new corporate account.", "stepLink": 4, "stepLinkLabel": "Review the registration step"}, {"title": "Opening \u2014 Opening the corporate account", "description": "Allow about 4 weeks: present the articles of incorporation, the certificate of incorporation, the corporate seal certificate, and the passports and ARCs of the directors. Documents issued outside Korea generally must be apostilled and translated into Korean."}, {"title": "Day +20 business days \u2014 End of anti-money-laundering restrictions", "description": "During the first 20 business days, transfer limits are reduced and opening a second account at another bank is blocked - a standard control measure used by Korean banks."}, {"title": "Day +60 days max \u2014 FDI registration to finalize with KOTRA", "description": "The foreign currency deposit certificate issued by your bank must be submitted to KOTRA to obtain your foreign-invested company certificate (\uc678\uad6d\uc778\ud22c\uc790\uae30\uc5c5\ub4f1\ub85d\uc99d), within a maximum of 60 days after the capital is paid in."}]}]$g5$::jsonb),
  (6, 'Register for taxes', 'Register for business and corporate tax with the National Tax Service.', 'https://www.hometax.go.kr',
    'Without a business registration certificate (사업자등록증), your company can neither issue tax invoices nor fully operate its corporate bank account - it''s the last administrative gate before normal operations. Foreign-invested companies must also appoint a Korean tax agent, responsible for preparing and filing all their returns in Korean with the NTS.' || E'\n\n' ||
    'Once these formalities are complete, your company enters the standard tax regime: progressive corporate income tax, 10% VAT, and, under certain conditions, a significant tax reduction for young companies.',
    $g6$[{"type": "columns", "eyebrow": "Formalities", "title": "Two formalities before filing", "subtitle": "These two steps determine your ability to legally invoice and report your income in Korea.", "columns": [{"icon": "document", "title": "Business registration certificate (\uc0ac\uc5c5\uc790\ub4f1\ub85d\uc99d)", "description": "Apply via Hometax or with the local tax office within 20 days of starting operations. Without this certificate, you cannot issue tax invoices (\uc138\uae08\uacc4\uc0b0\uc11c) or fully unlock your corporate bank account.", "items": ["Certificate of incorporation from the commercial court", "Corporate seal certificate", "Proof of lease for your head office"], "note": "Apply online via Hometax."}, {"icon": "id-card", "title": "Mandatory tax agent (\ud68c\uacc4\ub300\ub9ac\uc778)", "items": ["Prepares and files your VAT and corporate income tax returns", "All returns are drafted in Korean", "Generally billed monthly or quarterly, in addition to your accounting fees"], "note": "Foreign-invested companies must appoint a national tax agent (\ud68c\uacc4\ub300\ub9ac\uc778), a Korean accounting firm that becomes your official point of contact with the NTS."}]}, {"type": "stats", "eyebrow": "Taxation", "title": "Corporate income tax brackets (\ubc95\uc778\uc138)", "subtitle": "The applicable rate depends on your company's annual taxable profit, plus a local surtax equal to 10% of the national rate. Brackets in effect since January 1, 2026 - each bracket rose by one point compared to the previous scale.", "items": [{"label": "Up to 200 million KRW in taxable profit", "value": "10%", "description": "Almost all early-stage startups remain in this bracket."}, {"label": "From 200 million to 20 billion KRW", "value": "20%"}, {"label": "From 20 to 300 billion KRW", "value": "22%"}, {"label": "Above 300 billion KRW", "value": "25%"}]}, {"type": "stats", "eyebrow": "Key facts", "title": "Three figures to know", "subtitle": "Beyond the corporate tax brackets, three elements shape your day-to-day taxation.", "items": [{"label": "VAT (\ubd80\uac00\uac00\uce58\uc138)", "value": "10%", "description": "Standard rate applied to most goods and services, to be filed quarterly with the NTS."}, {"label": "Startup tax reduction", "value": "50 to 100%", "description": "During the first 5 years, depending on your head office's location - capped at a cumulative reduction of 500 million KRW.", "stepLink": 3, "stepLinkLabel": "See address options"}, {"label": "Annual filing", "value": "3 months", "description": "Deadline to file your corporate income tax return after your fiscal year closes."}]}]$g6$::jsonb),
  (7, 'Find funding', 'Apply to accelerators, grants, or preferential-rate loans.', NULL,
    'Between accelerator grants, R&D funding, and preferential public loans, the Korean government injects several billion KRW into its startup ecosystem every year. But most of this funding flows through selective programs: a company''s age, industry, and foreign-investor status determine access to each of them.' || E'\n\n' ||
    'Below are three entry points designed for foreign founders, followed by the criteria to check before putting together your application.',
    $g7$[{"type": "comparison", "eyebrow": "Comparison", "title": "Three entry points to fund your startup", "subtitle": "Each program targets a different profile - choose the one that matches your stage, your industry, and your existing investors.", "items": [{"name": "K-Startup Grand Challenge", "tag": "Grant + acceleration", "summary": "The Korean government's flagship program for startups founded by non-Koreans: about a hundred teams selected each edition, including a track reserved for foreign students. Winners receive on average 50 million KRW (up to 80 million) for product development, localization, and marketing, with 8 months of support through to COMEUP's Demo Day.", "requirements": ["Non-Korean startup less than 7 years old (10 years for deep tech)", "Priority sectors: AI, biotech, fintech, mobility, energy", "Privileged access to the D-8-4S visa for winners"]}, {"name": "TIPS", "tag": "R&D grant", "summary": "An R&D and commercialization grant that can exceed 100 million KRW per company, within a national pool raised to 5 billion KRW. Access isn't direct: you need a recommendation from an approved TIPS operator - an investment fund or accelerator partnered with the program.", "requirements": ["Startup less than 7 years old, recommended by an approved TIPS operator", "For foreign startups: at least USD 1 million already raised from foreign investors", "Can be combined with other sector-specific grants (food tech, deep tech...)"]}, {"name": "KOSME loans (\uc815\ucc45\uc790\uae08)", "tag": "Preferential-rate loan", "summary": "Public funds (\uc815\ucc45\uc790\uae08) from the Korea SMEs and Startups Agency finance cash flow, investment, and exports at below-market rates. For 2026, the national pool exceeds 4,400 billion KRW, geared toward manufacturing, productive investment, and international expansion.", "requirements": ["Company registered in Korea, generally for less than 7 years", "Apply through the new \"Policy Fund Navigator,\" which directs you to the right program based on your profile", "Can be combined with grants, contrary to popular belief"]}]}, {"type": "checklist", "eyebrow": "To check", "title": "Four criteria before applying", "subtitle": "These programs share common eligibility conditions - worth planning for before starting an application.", "items": [{"icon": "shield", "title": "Registered foreign investor (FDI) status", "description": "Most of these programs - and the tax benefits that come with them - assume your company has foreign-invested company (FDI) status, registered with KOTRA.", "stepLink": 5, "stepLinkLabel": "Review FDI registration"}, {"icon": "refresh", "title": "Less than 7 years old (10 for deep tech)", "description": "Your company's age is calculated from its official registration date, not from when the project began. The clock starts at the previous step.", "stepLink": 4, "stepLinkLabel": "Review the registration date"}, {"icon": "target", "title": "An eligible industry", "description": "AI, biotech, fintech, mobility, energy... Most programs for foreign founders target priority sectors defined each year by the Ministry of SMEs and Startups (MSS)."}, {"icon": "star", "title": "An operator or investor who recommends you", "description": "For TIPS in particular, you don't apply alone: an approved investment fund or accelerator must first select you and recommend you to the program."}]}]$g7$::jsonb),
  (8, 'Get insured', 'Enroll in the required national insurance schemes for employees.', NULL,
    'Enrollment in the 4 major social insurances (4대보험) must be completed within 14 days of hiring for health insurance, and by the 15th of the following month at the latest for the other three programs - missing this exposes you to retroactive contribution claims and, for some programs, penalties.' || E'\n\n' ||
    'Here''s how each of the four contributions is split between employer and employee, followed by three labor law benchmarks to know before your first hire.',
    $g8$[{"type": "stats", "eyebrow": "Contributions", "title": "The 4 mandatory social insurances (4\ub300\ubcf4\ud5d8)", "subtitle": "Each one is split differently between employer and employee - factor this into your total labor cost calculation.", "items": [{"label": "National Pension (\uad6d\ubbfc\uc5f0\uae08)", "value": "9.5%", "description": "Split 50/50: 4.75% employer, 4.75% employee. Rate raised from 9% to 9.5% on January 1, 2026, as part of a reform that will increase it by 0.5 points each year until it reaches 13% in 2033."}, {"label": "National Health Insurance (\uad6d\ubbfc\uac74\uac15\ubcf4\ud5d8)", "value": "7.19%", "description": "Split 50/50: 3.595% employer, 3.595% employee. Raised from 7.09% to 7.19% on January 1, 2026, plus an additional surcharge for long-term care insurance (\uc7a5\uae30\uc694\uc591\ubcf4\ud5d8), also split equally."}, {"label": "Employment Insurance (\uace0\uc6a9\ubcf4\ud5d8)", "value": "1.8% + employer share", "description": "Base rate split 50/50: 0.9% employer, 0.9% employee. The employer alone additionally pays 0.25% to 0.85%, depending on company size, for skills development (\uace0\uc6a9\uc548\uc815\u00b7\uc9c1\uc5c5\ub2a5\ub825\uac1c\ubc1c\uc0ac\uc5c5)."}, {"label": "Industrial Accident Compensation Insurance (\uc0b0\uc7ac\ubcf4\ud5d8)", "value": "Varies by industry", "description": "Fully paid by the employer (100%). The base rate varies widely by industry and risk level, with three additional flat-rate contributions: commuting accidents (0.06%), wage guarantee (0.06%, excluding the public sector), and asbestos compensation (0.006%, companies with 20 or more employees)."}]}, {"type": "stats", "eyebrow": "Key facts", "title": "Three benchmarks for your first hire", "subtitle": "Beyond social insurance contributions, these three rules apply from your very first employee.", "items": [{"label": "Minimum hourly wage (2026)", "value": "10,320 KRW", "description": "About 2,156,880 KRW per month based on 209 hours, up 2.9% from 2025. Applies to all employees, regardless of nationality."}, {"label": "Severance pay (\ud1f4\uc9c1\uae08)", "value": "30 days / year", "description": "Average wage \u00d7 30 days \u00d7 (days worked \u00f7 365), owed to any employee with at least one year of continuous service, regardless of the reason for departure."}, {"label": "Social security agreements", "value": "44 countries", "description": "Depending on the nationality and residency status of your foreign employees, these agreements may exempt them from certain pension or unemployment contributions in Korea.", "stepLink": 1, "stepLinkLabel": "Review your visa status"}]}]$g8$::jsonb);




    'The Korean government''s flagship program for startups founded by non-Koreans: about a hundred teams selected each edition, including a track reserved for foreign students. Winners receive on average 50,000,000 KRW (up to 80,000,000) for product development, localization, and marketing, with 8 months of support through to COMEUP''s Demo Day.',
    'Non-Korean startup less than 7 years old (10 years for deep tech). Priority sectors: AI, biotech, fintech, mobility, energy. Winners get privileged access to the D-8-4S visa.',
    'https://www.k-startupgc.org'),
  ('TIPS', 'rnd',
    'An R&D and commercialization grant that can exceed 100,000,000 KRW per company, within a national pool raised to 5,000,000,000 KRW. Access isn''t direct: you need a recommendation from an approved TIPS operator - an investment fund or accelerator partnered with the program.',
    'Startup less than 7 years old, recommended by an approved TIPS operator. Foreign startups need at least USD 1 million already raised from foreign investors. Can be combined with other sector-specific grants.',
    'https://www.jointips.or.kr'),
  ('KOSME loans (정책자금)', 'loan',
    'Public funds (정책자금) from the Korea SMEs and Startups Agency finance cash flow, investment, and exports at below-market rates. For 2026 the national pool exceeds 4,400,000,000,000 KRW, geared toward manufacturing, productive investment, and international expansion.',
    'Company registered in Korea, generally for less than 7 years. Apply through the Policy Fund Navigator, which directs you to the right program based on your profile. Can be combined with grants.',
    'https://www.kosme.or.kr'),
  ('Born2Global Acceleration', 'accelerator',
    'A government-backed acceleration track for foreign-market entry: mentoring, investor matching, and access to a network of over a thousand partner organizations for startups looking to expand beyond Korea.',
